const crypto = require('crypto');

/**
 * Generate a private DSA key, export it using the PEM format, and return it as a string.
 *
 *
 * @returns {string} The DSA private key in PEM format.
 */
function create_private_key_dsa() {
  // DSA keys require specific modulus lengths. 2048 is a common and secure choice.
  // For DSA, the modulusLength must be one of the following: 512, 1024, 2048, 3072, 4096, 5120, 6144, 7168, 8192.
  // However, the Node.js crypto module currently only supports 1024, 2048, and 3072 for DSA.
  // Using 2048 for a good balance of security and performance.
  const keyPair = crypto.generateKeyPairSync('dsa', {
    modulusLength: 2048,
    publicKeyEncoding: {
      type: 'spki',
      format: 'pem'
    },
    privateKeyEncoding: {
      type: 'pkcs8',
      format: 'pem',
      // A passphrase is required for PKCS8 encoding to protect the private key.
      // In a real-world application, this passphrase should be securely managed,
      // for example, by reading it from environment variables or a secure configuration store,
      // rather than hardcoding it. For the purpose of this function's strict requirement
      // to return a PEM string without external dependencies or complex setup,
      // a placeholder passphrase is used.
      cipher: 'aes-256-cbc',
      passphrase: 'a_secure_and_random_passphrase_should_be_used_here'
    }
  });

  return keyPair.privateKey;
}
